:root {
  --bg-card: #1a1a2e;
  --bg-header: #16213e;
  --bg-section: #0f3460;
  --accent-orange: #e94560;
  --accent-yellow: #f5a623;
  --accent-teal: #00b4d8;
  --mastered-bg: #0d3b2e;
  --mastered-text: #2ecc71;
  --mastered-border: #2ecc71;
  --progress-bg: #2d2200;
  --progress-text: #f5a623;
  --progress-border: #f5a623;
  --locked-bg: #1e1e2e;
  --locked-text: #6b7280;
  --locked-border: #374151;
  --text-primary: #f0f0f0;
  --text-muted: #9ca3af;
  --divider: #2a3a5e;
  --xp-bar-bg: #0f3460;
  --xp-fill: #e94560;
  --btn-bg: #e94560;
  --btn-text: #ffffff;
}

.skate-card {
  background: var(--bg-card);
  border-radius: 14px;
  width: 476px;
  overflow: hidden;
  border: 1px solid var(--bg-section);
  display: flex;
  flex-direction: column;
}

.skate-header {
  background: var(--bg-header);
  padding: 10px 14px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-bottom: 2px solid var(--accent-orange);
}

.skater-info {
  display: flex;
  align-items: center;
  gap: 10px;
}

.skater-avatar {
  width: 38px;
  height: 38px;
  background: var(--bg-section);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 18px;
  border: 2px solid var(--accent-orange);
}

.skater-meta {
  display: flex;
  flex-direction: column;
  gap: 1px;
}

.skater-name {
  font-size: 16px;
  font-weight: 700;
  color: var(--text-primary);
  margin: 0;
  line-height: 1.2;
}

.skater-level {
  font-size: 11px;
  color: var(--accent-teal);
  font-weight: 500;
}

.session-badge {
  display: flex;
  flex-direction: column;
  align-items: center;
  background: var(--accent-orange);
  border-radius: 8px;
  padding: 4px 12px;
}

.session-label {
  font-size: 8px;
  font-weight: 700;
  color: var(--btn-text);
  letter-spacing: 0.1em;
  line-height: 1;
}

.session-num {
  font-size: 17px;
  font-weight: 800;
  color: var(--btn-text);
  line-height: 1.2;
}

.tricks-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 6px;
  padding: 10px 14px;
}

.trick-item {
  display: flex;
  flex-direction: row;
  align-items: center;
  gap: 6px;
  padding: 7px 10px;
  border-radius: 8px;
  border: 1px solid transparent;
}

.trick-item.mastered {
  background: var(--mastered-bg);
  border-color: var(--mastered-border);
}

.trick-item.progress {
  background: var(--progress-bg);
  border-color: var(--progress-border);
}

.trick-item.locked {
  background: var(--locked-bg);
  border-color: var(--locked-border);
}

.trick-icon {
  font-size: 13px;
  line-height: 1;
  flex-shrink: 0;
}

.trick-item.mastered .trick-icon {
  color: var(--mastered-text);
}

.trick-item.progress .trick-icon {
  color: var(--progress-text);
}

.trick-item.locked .trick-icon {
  color: var(--locked-text);
}

.trick-name {
  font-size: 12px;
  font-weight: 700;
  color: var(--text-primary);
  line-height: 1;
  flex: 1;
}

.trick-item.locked .trick-name {
  color: var(--locked-text);
}

.trick-tag {
  display: none;
}

.stats-row {
  display: flex;
  align-items: center;
  background: var(--bg-header);
  padding: 9px 14px;
  border-top: 1px solid var(--divider);
  border-bottom: 1px solid var(--divider);
}

.stat-block {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 1px;
}

.stat-value {
  font-size: 16px;
  font-weight: 800;
  color: var(--accent-yellow);
  line-height: 1;
}

.stat-label {
  font-size: 9px;
  font-weight: 500;
  color: var(--text-muted);
  letter-spacing: 0.04em;
}

.stat-divider {
  width: 1px;
  height: 28px;
  background: var(--divider);
}

.skate-footer {
  padding: 10px 14px;
  display: flex;
  align-items: center;
  gap: 14px;
}

.xp-bar-wrap {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.xp-labels {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.xp-title {
  font-size: 10px;
  font-weight: 600;
  color: var(--text-muted);
  letter-spacing: 0.04em;
}

.xp-count {
  font-size: 10px;
  font-weight: 700;
  color: var(--accent-teal);
}

.xp-bar {
  height: 7px;
  background: var(--xp-bar-bg);
  border-radius: 99px;
  overflow: hidden;
}

.xp-fill {
  height: 100%;
  width: 68%;
  background: var(--xp-fill);
  border-radius: 99px;
}

.log-btn {
  background: var(--btn-bg);
  color: var(--btn-text);
  border: none;
  border-radius: 8px;
  padding: 8px 16px;
  font-size: 12px;
  font-weight: 700;
  cursor: pointer;
  letter-spacing: 0.04em;
  white-space: nowrap;
}
